mapper.select:
SELECT * FROM pmhub_wf_approval_task
WHERE status = 'pending'
AND (

    (approver_type = 'user' AND approver_id = #{userId})

    OR (approver_type = 'role' AND approver_value IN

            #{roleId}

    )


    OR (approver_type = 'dept' AND (

            FIND_IN_SET(#{deptId}, approver_value) > 0

    ))

)
ORDER BY created_time DESC

SELECT * FROM pmhub_wf_approval_task
WHERE extra_id = #{extraId} AND type = #{type}
ORDER BY created_time ASC

SELECT * FROM pmhub_wf_approval_task
WHERE status IN ('approved', 'rejected')
AND approval_time IS NOT NULL
AND (

    (approver_type = 'user' AND approver_id = #{userId})

    OR (approver_type = 'role' AND approver_value IN

            #{roleId}

    )


    OR (approver_type = 'dept' AND (

            FIND_IN_SET(#{deptId}, approver_value) > 0

    ))

)
ORDER BY approval_time DESC
